30	/**
31	 * Creates a form element, initialized with the current record, calling the saveContext on submit
32	 *
33	 * Wrapper around react-hook-form's useForm, FormContextProvider, and <form>.
34	 * Also sets up a FormGroupContext, and handles submission validation.
35	 *
36	 * @example
37	 *
38	 * const MyForm = ({ record, defaultValues, validate }) => (
39	 *    <Form record={record} defaultValues={defaultValues} validate={validate}>
40	 *        <Stack>
41	 *            <TextInput source="title" />
42	 *            <SaveButton />
43	 *        </Stack>
44	 *    </Form>
45	 * );
46	 *
47	 * @typedef {Object} Props the props you can use
48	 * @prop {Object} defaultValues
49	 * @prop {Function} validate
50	 * @prop {Function} save
51	 *
52	 * @see useForm
53	 * @see FormGroupContext
54	 *
55	 * @link https://react-hook-form.com/docs/useformcontext
56	 */
57	export function Form<RecordType = any>(props: FormProps<RecordType>) {
58	    const {
59	        children,
60	        id,
61	        className,
62	        noValidate = false,
63	        formRootPathname,
64	        warnWhenUnsavedChanges,
65	        WarnWhenUnsavedChangesComponent = WarnWhenUnsavedChanges,
66	    } = props;
67	    const record = useRecordContext(props);
68	    const resource = useResourceContext(props);
69	    const { form, formHandleSubmit } = useAugmentedForm(props);
70	    const sourceContext = React.useMemo<SourceContextValue>(
71	        () => ({
72	            getSource: (source: string) => source,
73	            getLabel: (source: string) =>
74	                `resources.${resource}.fields.${source}`,
75	        }),
76	        [resource]
77	    );
78	    const dataRouterContext = useContext(UNSAFE_DataRouterContext);
79	    const dataRouterStateContext = useContext(UNSAFE_DataRouterStateContext);
80	    if (
81	        warnWhenUnsavedChanges &&
82	        (!dataRouterContext || !dataRouterStateContext) &&
83	        process.env.NODE_ENV === 'development'
84	    ) {
85	        console.error(
86	            'Cannot use the warnWhenUnsavedChanges feature outside of a DataRouter. ' +
87	                'The warnWhenUnsavedChanges feature is disabled. ' +
88	                'Remove the warnWhenUnsavedChanges prop or convert your custom router to a Data Router.'
89	        );
90	    }
91	
92	    return (
93	        <OptionalRecordContextProvider value={record}>
94	            <SourceContextProvider value={sourceContext}>
95	                <FormProvider {...form}>
96	                    <FormGroupsProvider>
97	                        <form
98	                            onSubmit={formHandleSubmit}
99	                            noValidate={noValidate}
100	                            id={id}
101	                            className={className}
102	                        >
103	                            {children}
104	                        </form>
105	                        {warnWhenUnsavedChanges &&
106	                            dataRouterContext &&
107	                            dataRouterStateContext && (
108	                                <WarnWhenUnsavedChangesComponent
109	                                    enable
110	                                    formRootPathName={formRootPathname}
111	                                    formControl={form.control}
112	                                />
113	                            )}
114	                    </FormGroupsProvider>
115	                </FormProvider>
116	            </SourceContextProvider>
117	        </OptionalRecordContextProvider>
118	    );
119	}
120	
121	export type FormProps<RecordType = any> = FormOwnProps<RecordType> &
122	    Omit<UseFormProps, 'onSubmit'> & {
123	        validate?: ValidateForm;
124	        noValidate?: boolean;
125	        WarnWhenUnsavedChangesComponent?: React.ComponentType<{
126	            enable?: boolean;
127	            formRootPathName?: string;
128	            formControl?: any;
129	        }>;
130	    };
131	
132	export interface FormOwnProps<RecordType = any> {
133	    children: ReactNode;
134	    className?: string;
135	    defaultValues?: any;
136	    formRootPathname?: string;
137	    id?: string;
138	    record?: Partial<RaRecord>;
139	    resource?: string;
140	    onSubmit?: SubmitHandler<FieldValues> | SaveHandler<RecordType>;
141	    warnWhenUnsavedChanges?: boolean;
142	    sanitizeEmptyValues?: boolean;
143	    disableInvalidFormNotification?: boolean;
144	}
