14	export const useRecordFromLocation = (
15	    props: UseRecordFromLocationOptions = {}
16	) => {
17	    const { searchSource, stateSource } = props;
18	    const location = useLocation();
19	    const [recordFromLocation, setRecordFromLocation] = useState(() =>
20	        getRecordFromLocation(location, {
21	            stateSource,
22	            searchSource,
23	        })
24	    );
25	
26	    // To avoid having the form resets when the location changes but the final record is the same
27	    // This is needed for forms such as TabbedForm or WizardForm that may change the location for their sections
28	    const previousRecordRef = useRef(recordFromLocation);
29	
30	    useEffect(() => {
31	        const newRecordFromLocation = getRecordFromLocation(location, {
32	            stateSource,
33	            searchSource,
34	        });
35	
36	        if (!isEqual(newRecordFromLocation, previousRecordRef.current)) {
37	            previousRecordRef.current = newRecordFromLocation;
38	            setRecordFromLocation(newRecordFromLocation);
39	        }
40	    }, [location, stateSource, searchSource]);
