54	export const getRecordFromLocation = (
55	    { state, search }: RouterLocation,
56	    {
57	        searchSource = 'source',
58	        stateSource = 'record',
59	    }: {
60	        searchSource?: string;
61	        stateSource?: string;
62	    } = {}
63	): Partial<RaRecord> | null => {
64	    if (state && state[stateSource]) {
65	        return state[stateSource];
66	    }
67	    if (search) {
68	        try {
69	            const searchParams = parse(search);
70	            const source = searchParams[searchSource];
71	            if (source) {
72	                if (Array.isArray(source)) {
73	                    console.error(
74	                        `Failed to parse location ${searchSource} parameter '${search}'. To pre-fill some fields in the Create form, pass a stringified ${searchSource} parameter (e.g. '?${searchSource}={"title":"foo"}')`
75	                    );
