28	 * Wrapper around react-hook-form's useForm
29	 *
30	 * This hook adds the following features to react-hook-form's useForm:
31	 *
32	 * - form initialization based on RecordContext
33	 * - validation based on a validate function
34	 * - sanitization of empty values
35	 * - notification on invalid form
36	 * - stop form submission event propagation
37	 */
38	export const useAugmentedForm = <RecordType = any>(
39	    props: UseAugmentedFormProps<RecordType>
40	) => {
41	    const {
42	        criteriaMode = 'firstError',
43	        defaultValues,
44	        formRootPathname,
45	        resolver,
46	        resetOptions,
47	        reValidateMode = 'onChange',
48	        onSubmit,
49	        sanitizeEmptyValues,
50	        validate,
51	        disableInvalidFormNotification,
52	        ...rest
53	    } = props;
54	    const saveContext = useSaveContext();
55	    const record = useRecordContext(props);
56	
57	    const defaultValuesIncludingRecord = useMemo(
58	        () => getFormInitialValues(defaultValues, record),
59	        // eslint-disable-next-line
60	        [
61	            // eslint-disable-next-line
62	            JSON.stringify({
63	                defaultValues:
64	                    typeof defaultValues === 'function'
65	                        ? 'function'
66	                        : defaultValues,
67	                record,
68	            }),
69	        ]
70	    );
71	
72	    const finalResolver = resolver
73	        ? resolver
74	        : validate
75	          ? getSimpleValidationResolver(validate)
76	          : undefined;
77	
78	    const form = useForm({
79	        criteriaMode,
80	        defaultValues: defaultValuesIncludingRecord,
81	        reValidateMode,
82	        resolver: finalResolver,
83	        ...rest,
84	    });
85	
86	    const formRef = useRef(form);
87	    const { reset, formState } = form;
88	    const { isReady } = formState;
89	
90	    const previousRecordId = useRef(record?.id);
91	
92	    useEffect(() => {
93	        const recordIdChanged = record?.id !== previousRecordId.current;
94	        previousRecordId.current = record?.id;
95	
96	        reset(
97	            defaultValuesIncludingRecord,
98	            recordIdChanged ? undefined : resetOptions
99	        );
100	    }, [defaultValuesIncludingRecord, reset, resetOptions, record?.id]);
101	
102	    // notify on invalid form
103	    useNotifyIsFormInvalid(form.control, !disableInvalidFormNotification);
104	
105	    const recordFromLocation = useRecordFromLocation();
106	    const recordFromLocationApplied = useRef(false);
107	    useEffect(() => {
108	        if (!isReady) return;
109	        if (recordFromLocation && !recordFromLocationApplied.current) {
110	            reset(merge({}, defaultValuesIncludingRecord, recordFromLocation), {
111	                keepDefaultValues: true,
112	            });
113	            recordFromLocationApplied.current = true;
114	        }
115	    }, [defaultValuesIncludingRecord, recordFromLocation, reset, isReady]);
116	
117	    // submit callbacks
118	    const handleSubmit = useCallback(
119	        async (values, event) => {
120	            let errors;
121	            const finalValues = sanitizeEmptyValues
122	                ? sanitizeValues(values, record)
123	                : values;
124	            if (onSubmit) {
125	                errors = await onSubmit(finalValues, event);
126	            }
127	            if (onSubmit == null && saveContext?.save) {
128	                errors = await saveContext.save(finalValues, event);
129	            }
130	            if (errors != null) {
131	                setSubmissionErrors(errors, formRef.current.setError);
132	            }
133	        },
134	        [onSubmit, saveContext, sanitizeEmptyValues, record]
135	    );
