137	    const formHandleSubmit = useCallback(
138	        (event: BaseSyntheticEvent) => {
139	            if (!event.defaultPrevented) {
140	                // Prevent outer forms to receive the event
141	                event.stopPropagation();
142	                form.handleSubmit(handleSubmit)(event);
143	            }
144	            return;
145	        },
146	        [form, handleSubmit]
147	    );
