cle with this title already exists. The title must be unique.',\n                        });\n                    },\n                } as any\n            }\n        >\n            <Resource\n                name=\"posts\"\n                create={() => (\n                    <Create resource=\"posts\" record={{ title: 'Lorem ipsum' }}>\n                        <SimpleForm toolbar={AlwaysOnToolbar}>\n                            <TextInput source=\"title\" />\n                            <FormInspector />\n                        </SimpleForm>\n                    </Create>\n                )}\n            />\n        </Admin>\n    </MemoryRouter>\n);\n\nexport const ServerValidationError = () => (\n    <MemoryRouter initialEntries={['/posts/create']}>\n        <Admin\n            dataProvider={\n                {\n                    create: (resource, { data }) => {\n                        console.log(`reject create on ${resource}: `, data);\n                        return Promise.reject({\n                            data,\n                            body: {\n                                errors: {\n                                    title: 'An article with this title already exists. The title must be unique.',\n                                },\n                            },\n                        });\n                    },\n                } as any\n            }\n        >\n            <Resource\n                name=\"posts\"\n                create={() => (\n                    <Create resource=\"posts\" record={{ title: 'Lorem ipsum' }}>\n                        <SimpleForm toolbar={AlwaysOnToolbar}>\n                            <TextInput source=\"title\" />\n                            <FormInspector />\n                        </SimpleForm>\n                    </Create>\n                )}\n            />\n        </Admin>\n    </MemoryRouter>\n);\n\nexport const Sx = () => (\n    <Wrapper>\n        <TextInput\n            source=\"title\"\n  