t AlwaysOnToolbar = (\n    <Toolbar>\n        <SaveButton alwaysEnable />\n    </Toolbar>\n);\n\nexport const ValueUndefined = ({ onSuccess = console.log }) => (\n    <AdminContext\n        dataProvider={\n            {\n                getOne: () => Promise.resolve({ data: { id: 123 } }),\n                update: (resource, { data }) => Promise.resolve({ data }),\n            } as any\n        }\n        defaultTheme=\"light\"\n    >\n        <Edit\n            resource=\"posts\"\n            id=\"123\"\n            sx={{ width: 600 }}\n            mutationOptions={{ onSuccess }}\n        >\n            <SimpleForm toolbar={AlwaysOnToolbar}>\n                <TextInput source=\"title\" />\n                <FormInspector />\n            </SimpleForm>\n        </Edit>\n    </AdminContext>\n);\n\nexport const ValueNull = ({ onSuccess = console.log }) => (\n    <AdminContext\n        dataProvider={\n            {\n                getOne: () =>\n                    Promise.resolve({ data: { id: 123, title: null } }),\n                update: (resource, { data }) => Promise.resolve({ data }),\n            } as any\n        }\n        defaultTheme=\"light\"\n    >\n        <Edit\n            resource=\"posts\"\n            id=\"123\"\n            sx={{ width: 600 }}\n            mutationOptions={{ onSuccess }}\n        >\n            <SimpleForm toolbar={AlwaysOnToolbar}>\n                <TextInput source=\"title\" />\n                <FormInspector />\n            </SimpleForm>\n        </Edit>\n    </AdminContext>\n);\n\nexport const Parse = ({ onSuccess = console.log }) => (\n    <AdminContext defaultTheme=\"light\">\n        <Create\n            resource=\"posts\"\n            record={{ id: 123, title: 'Lorem ipsum' }}\n            sx={{ width: 600 }}\n            mutationOptions={{ onSuccess }}\n        >\n            <SimpleForm>\n                <TextInput\n                    source=\"title\"\n                    parse={v => (v === 'foo' ? 'bar' : v)}\n                />\n            </SimpleForm>\n        </Create>\n    </AdminContext>\n);\n"],"version":3}
