ussian' },\n    { id: 2, first_name: 'Victor', last_name: 'Hugo', language: 'French' },\n    {\n        id: 3,\n        first_name: 'William',\n        last_name: 'Shakespeare',\n        language: 'English',\n    },\n    {\n        id: 4,\n        first_name: 'Charles',\n        last_name: 'Baudelaire',\n        language: 'French',\n    },\n    { id: 5, first_name: 'Marcel', last_name: 'Proust', language: 'French' },\n];\n\nexport const dataProviderWithAuthors = {\n    getOne: () =>\n        Promise.resolve({\n            data: {\n                id: 1,\n                title: 'War and Peace',\n                author: 1,\n                summary:\n                    \"War and Peace broadly focuses on Napoleon's invasion of Russia, and the impact it had on Tsarist society. The book explores themes such as revolution, revolution and empire, the growth and decline of various states and the impact it had on their economies, culture, and society.\",\n                year: 1869,\n            },\n        }),\n    getMany: (_resource, params) =>\n        Promise.resolve({\n            data: authors.filter(author => params.ids.includes(author.id)),\n        }),\n} as any;\n\nexport const Basic = ({ dataProvider = dataProviderWithAuthors }) => (\n    <TestMemoryRouter initialEntries={['/books/1/show']}>\n        <CoreAdmin\n            dataProvider={dataProvider}\n            queryClient={\n                new QueryClient({\n                    defaultOptions: {\n                        queries: {\n                            retry: false,\n                        },\n                    },\n                })\n            }\n        >\n            <Resource name=\"authors\" />\n            <Resource\n                name=\"books\"\n                show={\n                    <ShowBase>\n                        <ReferenceFieldBase source=\"author\" reference=\"authors\">\n                            <MyReferenceField>\n                                <TextField source=\"first_name\" />\n                            </MyReferenceField>\n                        </ReferenceFieldBase>\n                    </ShowBase>\n                }\n            />\n        </CoreAdmin>\n    </TestMemoryRouter>\n);\n\nconst dataProviderWithAuthorsError = {\n    getOne: () =>\n        Promise.resolve({\n            data: {\n                id: 1,\n                title: 'War and Peace',\n                author: 1,\n                summary:\n                    \"War and Peace broadly focuses on Napoleon's invasion of Russia, and the impact it had on Tsarist society. The book explores themes such as revolution, revolution and empire, the growth and decline of various states and the impact it had on their economies, culture, and society.\",\n                year: 1869,\n            },\n        }),\n    getMany: _resource => Promise.reject('Error'),\n} as any;\n\nexport const Error = ({ dataProvider = dataProviderWithAuthorsError }) => (\n    <TestMemoryRouter initialEntries={['/books/1/show']}>\n        <CoreAdmin\n            dataProvider={dataProvider}\n            queryClient={\n                new QueryClient({\n                    defaultOptions: {\n                        queries: {\n                            retry: false,\n                        },\n                    },\n                })\n            }\n        >\n            <Resource name=\"authors\" />\n            <Resource\n                name=\"books\"\n                show={\n                    <ShowBase>\n                        <ReferenceFieldBase source=\"author\" reference=\"authors\">\n                            <MyReferenceField>\n                                <TextField source=\"first_name\" />\n                            </MyReferenceField>\n                        </ReferenceFieldBase>\n                    </ShowBase>\n                }\n            />\n        </CoreAdmin>\n    </TestMemoryRouter>\n);\n\nconst dataProviderWithAuthorsLoading = {\n    getOne: () =>\n        Promise.resolve({\n            data: {\n                id: 1,\n                title: 'War and Peace',\n                author: 1,\n                summary:\n                    \"War and Peace broadly focuses on Napoleon's invasion of Russia, and the impact it had on Tsarist society. The book explores themes such as revolution, revolution and empire, the growth and decline of various states and the impact it had on their economies, culture, and society.\",\n                year: 1869,\n            },\n        }),\n    getMany: _resource => new Promise(() => {}),\n} as any;\n\nexport const Loading = ({ dataProvider = dataProviderWithAuthorsLoading }) => (\n    <TestMemoryRouter initialEntries={['/books/1/show']}>\n        <CoreAdmin\n            dataProvider={dataProvider}\n            queryClient={\n                new QueryClient({\n                    defaultOptions: {\n                        queries: {\n                            retry: false,\n                        },\n                    },\n                })\n            }\n        >\n            <Resource name=\"authors\" />\n            <Resource\n                name=\"books\"\n                show={\n                    <ShowBase>\n                        <ReferenceFieldBase source=\"author\" reference=\"authors\">\n                            <MyReferenceField>\n                                <TextField source=\"first_name\" />\n                            </MyReferenceField>\n                        </ReferenceFieldBase>\n                    </ShowBase>\n                }\n            />\n        </CoreAdmin>\n    </TestMemoryRouter>\n);\n\nconst BookShowQueryOptions = () => {\n    const [enabled, setEnabled] = React.useState(false);\n    return (\n        <ShowBase>\n            <>\n                <button onClick={() => setEnabled(!enabled)}>\n                    Enable the query\n                </button>\n                <TextField source=\"title\" />\n                <ReferenceFieldBase\n                    reference=\"authors\"\n                    source=\"author\"\n                    queryOptions={{ enabled }}\n                >\n                    <MyReferenceField>\n                        <TextField source=\"last_name\" />\n                    </MyReferenceField>\n                </ReferenceFieldBase>\n                <button type=\"submit\">Save</button>\n            </>\n        </ShowBase>\n    );\n};\n\nexport const QueryOptions = () => (\n    <TestMemoryRouter initialEntries={['/books/1/show']}>\n        <CoreAdmin\n            dataProvider={fakeRestDataProvider(\n                {\n                    books: [\n                        {\n                            id: 1,\n                            title: 'War and Peace',\n                            author: 1,\n                            summary:\n                                \"War and Peace broadly focuses on Napoleon's invasion of Russia, and the impact it had on Tsarist society. The book explores themes such as revolution, revolution and empire, the growth and decline of various states and the impact it had on their economies, culture, and society.\",\n                            year: 1869,\n                        },\n                    ],\n                    authors: [\n                        {\n                            id: 1,\n                            first_name: 'Leo',\n                            last_name: 'Tolstoy',\n                            language: 'Russian',\n                        },\n                        {\n                            id: 2,\n                            first_name: 'Victor',\n                            last_name: 'Hugo',\n                            language: 'French',\n                        },\n                        {\n                            id: 3,\n                            first_name: 'William',\n                            last_name: 'Shakespeare',\n                            language: 'English',\n                        },\n                        {\n                            id: 4,\n                            first_name: 'Charles',\n                            last_name: 'Baudelaire',\n                            language: 'French',\n                        },\n                        {\n                            id: 5,\n                            first_name: 'Marcel',\n                            last_name: 'Proust',\n                            language: 'French',\n                        },\n                    ],\n                },\n                process.env.NODE_ENV === 'development'\n            )}\n            queryClient={\n                new QueryClient({\n                    defaultOptions: {\n                        queries: {\n                            retry: false,\n                        },\n                    },\n                })\n            }\n        >\n            <Resource name=\"books\" show={BookShowQueryOptions} />\n        </CoreAdmin>\n    </TestMemoryRouter>\n);\n\nconst BookShowMeta = () => {\n    return (\n        <ShowBase>\n            <>\n                <TextField source=\"title\" />\n                <ReferenceFieldBase\n                    reference=\"authors\"\n                    source=\"author\"\n                    queryOptions={{ meta: { test: true } }}\n                >\n                    <MyReferenceField>\n                        <TextField source=\"last_name\" />\n                    </MyReferenceField>\n                </ReferenceFieldBase>\n            </>\n        </ShowBase>\n    );\n};\n\nexport const Meta = ({\n    dataProvider = fakeRestDataProvider(\n        {\n            books: [\n                {\n                    id: 1,\n                    title: 'War and Peace',\n                    author: 1,\n                    summary:\n                        \"War and Peace broadly focuses on Napoleon's invasion of Russia, and the impact it had on Tsarist society. The book explores themes such as revolution, revolution and empire, the growth and decline of various states and the impact it had on their economies, culture, and society.\",\n                    year: 1869,\n                },\n            ],\n            authors: [\n                {\n                    id: 1,\n                    first_name: 'Leo',\n                    last_name: 'Tolstoy',\n                    language: 'Russian',\n                },\n                {\n                    id: 2,\n                    first_name: 'Victor',\n                    last_name: 'Hugo',\n                    language: 'French',\n                },\n                {\n                    id: 3,\n                    first_name: 'William',\n                    last_name: 'Shakespeare',\n                    language: 'English',\n                },\n                {\n                    id: 4,\n                    first_name: 'Charles',\n                    last_name: 'Baudelaire',\n                    language: 'French',\n                },\n                {\n                    id: 5,\n                    first_name: 'Marcel',\n                    last_name: 'Proust',\n                    language: 'French',\n                },\n            ],\n        },\n        process.env.NODE_ENV === 'development'\n    ),\n}: {\n    dataProvider: DataProvider;\n}) => (\n    <TestMemoryRouter initialEntries={['/books/1/show']}>\n        <CoreAdmin\n            dataProvider={dataProvider}\n            queryClient={\n                new QueryClient({\n                    defaultOptions: {\n                        queries: {\n                            retry: false,\n                        },\n                    },\n                })\n            }\n        >\n            <Resource name=\"books\" show={BookShowMeta} />\n        </CoreAdmin>\n    </TestMemoryRouter>\n);\n\nconst MyReferenceField = (props: { children: React.ReactNode }) => {\n    const context = useReferenceFieldContext();\n\n    if (context.isPending) {\n        return <p>Loading...</p>;\n    }\n\n    if (context.error) {\n        return <p style={{ color: 'red' }}>{context.error}</p>;\n    }\n    return props.children;\n};\n\nconst TextField = ({ source }: { source: string }) => {\n    const value = useFieldValue({ source });\n    return <p>{value}</p>;\n};\n"],"version":3}
