ct';\n\nimport {\n    minLength,\n    required,\n    ResourceContextProvider,\n    testDataProvider,\n    TestMemoryRouter,\n} from 'ra-core';\n\nimport {\n    fireEvent,\n    isInaccessible,\n    render,\n    screen,\n    waitFor,\n} from '@testing-library/react';\n\nimport { AdminContext } from '../AdminContext';\nimport { TabbedForm } from './TabbedForm';\nimport { TabbedFormClasses } from './TabbedFormView';\nimport { TextInput } from '../input';\nimport { EncodedPaths } from './TabbedForm.stories';\n\ndescribe('<TabbedForm />', () => {\n    it('should display the tabs', () => {\n        render(\n            <TestMemoryRouter>\n                <AdminContext dataProvider={testDataProvider()}>\n                    <ResourceContextProvider value=\"posts\">\n                        <TabbedForm>\n                            <TabbedForm.Tab label=\"tab1\" />\n                            <TabbedForm.Tab label=\"tab2\" />\n                        </TabbedForm>\n                    </ResourceContextProvider>\n                </AdminContext>\n            </TestMemoryRouter>\n        );\n\n        const tabs = screen.queryAllByRole('tab');\n        expect(tabs.length).toEqual(2);\n    });\n\n    it('should display the tabs contents with encoded complex record identifiers', async () => {\n        render(<EncodedPaths />);\n\n        const tabs = await screen.findAllByRole('tab');\n        expect(tabs.length).toEqual(2);\n        await screen.findByLabelText('Title');\n    });\n\n    it('should set the style of an inactive Tab button with errors', async () => {\n        render(\n            <TestMemoryRouter initialEntries={['/1']}>\n                <AdminContext dataProvider={testDataProvider()}>\n                    <ResourceContextProvider value=\"posts\">\n                        <TabbedForm mode=\"onBlur\">\n                            <TabbedForm.Tab label=\"tab1\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"title\"\n                                    validate={required()}\n                                />\n                            </TabbedForm.Tab>\n                            <TabbedForm.Tab label=\"tab2\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"description\"\n                                    validate={minLength(10)}\n                                />\n                            </TabbedForm.Tab>\n                        </TabbedForm>\n                    </ResourceContextProvider>\n                </AdminContext>\n            </TestMemoryRouter>\n        );\n\n        const tabs = screen.getAllByRole('tab');\n        fireEvent.click(tabs[1]);\n        const input = screen.getByLabelText(\n            'resources.posts.fields.description'\n        );\n        fireEvent.change(input, { target: { value: 'foo' } });\n        fireEvent.blur(input);\n        fireEvent.click(tabs[0]);\n\n        await waitFor(() => {\n            expect(\n                tabs[1].classList.contains(TabbedFormClasses.errorTabButton)\n            ).toEqual(true);\n        });\n\n        expect(\n            tabs[0].classList.contains(TabbedFormClasses.errorTabButton)\n        ).toEqual(false);\n    });\n\n    it('should set the style of an active Tab button with errors', async () => {\n        render(\n            <TestMemoryRouter initialEntries={['/1']}>\n                <AdminContext dataProvider={testDataProvider()}>\n                    <ResourceContextProvider value=\"posts\">\n                        <TabbedForm mode=\"onBlur\">\n                            <TabbedForm.Tab label=\"tab1\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"title\"\n                                    validate={required()}\n                                />\n                            </TabbedForm.Tab>\n                            <TabbedForm.Tab label=\"tab2\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"description\"\n                                    validate={required()}\n                                />\n                            </TabbedForm.Tab>\n                        </TabbedForm>\n                    </ResourceContextProvider>\n                </AdminContext>\n            </TestMemoryRouter>\n        );\n\n        const tabs = screen.getAllByRole('tab');\n        fireEvent.click(tabs[1]);\n        const input = screen.getByLabelText(\n            'resources.posts.fields.description *'\n        );\n        fireEvent.blur(input);\n        await waitFor(() => {\n            expect(\n                tabs[1].classList.contains(TabbedFormClasses.errorTabButton)\n            ).toEqual(true);\n        });\n        expect(\n            tabs[0].classList.contains(TabbedFormClasses.errorTabButton)\n        ).toEqual(false);\n    });\n\n    it('should set the style of any Tab button with errors on submit', async () => {\n        render(\n            <TestMemoryRouter initialEntries={['/1']}>\n                <AdminContext dataProvider={testDataProvider()}>\n                    <ResourceContextProvider value=\"posts\">\n                        <TabbedForm mode=\"onBlur\">\n                            <TabbedForm.Tab label=\"tab1\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"title\"\n                                    validate={required()}\n                                />\n                            </TabbedForm.Tab>\n                            <TabbedForm.Tab label=\"tab2\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"description\"\n                                    validate={minLength(10)}\n                                />\n                            </TabbedForm.Tab>\n                        </TabbedForm>\n                    </ResourceContextProvider>\n                </AdminContext>\n            </TestMemoryRouter>\n        );\n\n        const tabs = screen.getAllByRole('tab');\n        fireEvent.click(tabs[1]);\n        const input = screen.getByLabelText(\n            'resources.posts.fields.description'\n        );\n        fireEvent.change(input, { target: { value: 'fooooooooo' } });\n        fireEvent.click(screen.getByLabelText('ra.action.save'));\n        await waitFor(() => {\n            expect(\n                tabs[0].classList.contains(TabbedFormClasses.errorTabButton)\n            ).toEqual(true);\n        });\n        expect(\n            tabs[1].classList.contains(TabbedFormClasses.errorTabButton)\n        ).toEqual(false);\n    });\n\n    it('should sync tabs with location by default', () => {\n        let location;\n        render(\n            <TestMemoryRouter\n                initialEntries={['/']}\n                locationCallback={l => {\n                    location = l;\n                }}\n            >\n                <AdminContext dataProvider={testDataProvider()}>\n                    <ResourceContextProvider value=\"posts\">\n                        <TabbedForm>\n                            <TabbedForm.Tab label=\"tab1\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"title\"\n                                    validate={required()}\n                                />\n                            </TabbedForm.Tab>\n                            <TabbedForm.Tab label=\"tab2\">\n                                <TextInput\n                                    defaultValue=\"\"\n                                    source=\"description\"\n    