1B,EAAE,CAAC,yCAAyC,EAAE;;;;;wBACpC,YAAY,GAAG,IAAA,mCAAgB,EAAC;4BAClC,gBAAgB,EAAE;gCACd,OAAA,OAAO,CAAC,OAAO,CAAC;oCACZ,IAAI,EAAE;wCACF,EAAE,EAAE,EAAE,CAAC,EAAE,KAAK,EAAE,OAAO,EAAE;wCACzB,EAAE,EAAE,EAAE,CAAC,EAAE,KAAK,EAAE,OAAO,EAAE;qCAC5B;oCACD,KAAK,EAAE,CAAC;oCACR,IAAI,EAAE;wCACF,MAAM,EAAE;4CACJ,EAAE,GAAG,EAAE,KAAK,EAAE,KAAK,EAAE,CAAC,EAAE;4CACxB,EAAE,GAAG,EAAE,KAAK,EAAE,KAAK,EAAE,CAAC,EAAE;yCAC3B;qCACJ;iCACJ,CAAQ;4BAZT,CAYS;yBAChB,CAAC,CAAC;wBAEG,qBAAqB,GAAG;4BAC1B,IAAM,WAAW,GAAG,IAAA,iEAA+B,EAAC;gCAChD,QAAQ,EAAE,SAAS;gCACnB,MAAM,EAAE,IAAI;gCACZ,MAAM,EAAE,EAAE,EAAE,EAAE,GAAG,EAAE,IAAI,EAAE,aAAa,EAAE;gCACxC,SAAS,EAAE,OAAO;gCAClB,MAAM,EAAE,WAAW;6BACtB,CAAC,CAAC;4BAEH,OAAO,CACH;;gCACuB,GAAG;gCACtB,iCAAM,IAAI,CAAC,SAAS,CAAC,WAAW,CAAC,IAAI,EAAE,IAAI,CAAC,CAAO,CACpD,CACN,CAAC;wBACN,CAAC,CAAC;wBAEF,IAAA,cAAM,EACF,oBAAC,uBAAgB,IAAC,YAAY,EAAE,YAAY;4BACxC,oBAAC,qBAAqB,OAAG,CACV,CACtB,CAAC;wBAEF,qBAAM,cAAM,CAAC,UAAU,CACnB,8DAA8D,CACjE,EAAA;;wBAFD,SAEC,CAAC;;;;aACL,CAAC,CAAC;IACP,CAAC,CAAC,CAAC;AACP,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/packages/ra-core/src/controller/field/useReferenceManyFieldController.spec.tsx"],"sourcesContent":["import * as React from 'react';\nimport { fireEvent, render, screen, waitFor } from '@testing-library/react';\nimport expect from 'expect';\n\nimport { testDataProvider } from '../../dataProvider/testDataProvider';\nimport { CoreAdminContext } from '../../core';\nimport { useReferenceManyFieldController } from './useReferenceManyFieldController';\nimport { memoryStore } from '../../store';\n\nconst ReferenceManyFieldController = props => {\n    const { children, page = 1, perPage = 25, ...rest } = props;\n    const controllerProps = useReferenceManyFieldController({\n        page,\n        perPage,\n        ...rest,\n    });\n    return children(controllerProps);\n};\n\ndescribe('useReferenceManyFieldController', () => {\n    it('should set isLoading to true when related records are not yet fetched', async () => {\n        const ComponentToTest = ({ isLoading }: { isLoading?: boolean }) => {\n            return <div>isLoading: {isLoading?.toString()}</div>;\n        };\n        const dataProvider = testDataProvider({\n            getManyReference: () => Promise.resolve({ data: [], total: 0 }),\n        });\n\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"foo\"\n                    source=\"items\"\n                    reference=\"bar\"\n                    target=\"foo_id\"\n                    record={{ id: 1, items: [1, 2] }}\n                >\n                    {props => <ComponentToTest {...props} />}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n\n        expect(screen.queryByText('isLoading: true')).not.toBeNull();\n        await waitFor(() => {\n            expect(screen.queryByText('isLoading: false')).not.toBeNull();\n        });\n    });\n\n    it('should set isLoading to false when related records have been fetched and there are results', async () => {\n        const ComponentToTest = ({ isLoading }: { isLoading?: boolean }) => {\n            return <div>isLoading: {isLoading?.toString()}</div>;\n        };\n        const dataProvider = testDataProvider({\n            getManyReference: () =>\n                Promise.resolve({\n                    data: [\n                        { id: 1, title: 'hello' },\n                        { id: 2, title: 'world' },\n                    ],\n                    total: 2,\n                }) as any,\n        });\n\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"foo\"\n                    source=\"items\"\n                    reference=\"bar\"\n                    target=\"foo_id\"\n                    record={{ id: 1, items: [1, 2] }}\n                >\n                    {props => <ComponentToTest {...props} />}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n\n        expect(screen.queryByText('isLoading: true')).not.toBeNull();\n        await waitFor(() => {\n            expect(screen.queryByText('isLoading: false')).not.toBeNull();\n        });\n    });\n\n    it('should call dataProvider.getManyReferences on mount', async () => {\n        const dataProvider = testDataProvider({\n            getManyReference: jest\n                .fn()\n                .mockResolvedValue({ data: [], total: 0 }),\n        });\n\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"id\"\n                    record={{ id: 123, name: 'James Joyce' }}\n                    reference=\"books\"\n                    target=\"author_id\"\n                >\n                    {() => 'null'}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n\n        await waitFor(() => {\n            expect(dataProvider.getManyReference).toHaveBeenCalledWith(\n                'books',\n                {\n                    id: 123,\n                    target: 'author_id',\n                    pagination: { page: 1, perPage: 25 },\n                    sort: { field: 'id', order: 'DESC' },\n                    filter: {},\n                    signal: undefined,\n                }\n            );\n        });\n    });\n\n    it('should pass data to children function', async () => {\n        const children = jest.fn().mockReturnValue('children');\n        const dataProvider = testDataProvider({\n            getManyReference: () =>\n                Promise.resolve({\n                    data: [\n                        { id: 1, title: 'hello' },\n                        { id: 2, title: 'world' },\n                    ],\n                    total: 2,\n                }) as any,\n        });\n\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"id\"\n                    record={{ id: 123, name: 'James Joyce' }}\n                    reference=\"books\"\n                    target=\"author_id\"\n                >\n                    {children}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n        await waitFor(() => {\n            expect(children).toHaveBeenCalledWith(\n                expect.objectContaining({\n                    data: [\n                        { id: 1, title: 'hello' },\n                        { id: 2, title: 'world' },\n                    ],\n                    total: 2,\n                    hasPreviousPage: false,\n                    hasNextPage: false,\n                })\n            );\n        });\n    });\n\n    it('should handle partial pagination', async () => {\n        const children = jest.fn().mockReturnValue('children');\n        const dataProvider = testDataProvider({\n            getManyReference: () =>\n                Promise.resolve({\n                    data: [\n                        { id: 1, title: 'hello' },\n                        { id: 2, title: 'world' },\n                    ],\n                    pageInfo: {\n                        hasPreviousPage: false,\n                        hasNextPage: false,\n                    },\n                }) as any,\n        });\n\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"id\"\n                    record={{ id: 123, name: 'James Joyce' }}\n                    reference=\"books\"\n                    target=\"author_id\"\n                >\n                    {children}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n        await waitFor(() => {\n            expect(children).toHaveBeenCalledWith(\n                expect.objectContaining({\n                    total: undefined,\n                    hasPreviousPage: false,\n                    hasNextPage: false,\n                })\n            );\n        });\n    });\n\n    it('should support custom source', async () => {\n        const dataProvider = testDataProvider({\n            getManyReference: jest\n                .fn()\n                .mockResolvedValue({ data: [], total: 0 }),\n        });\n\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"uniqueName\"\n                    record={{\n                        id: 123,\n                        uniqueName: 'jamesjoyce256',\n                        name: 'James Joyce',\n                    }}\n                    reference=\"books\"\n                    target=\"author_id\"\n                >\n                    {() => 'null'}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n\n        await waitFor(() => {\n            expect(dataProvider.getManyReference).toHaveBeenCalledWith(\n                'books',\n                {\n                    id: 'jamesjoyce256',\n                    target: 'author_id',\n                    pagination: { page: 1, perPage: 25 },\n                    sort: { field: 'id', order: 'DESC' },\n                    filter: {},\n                    signal: undefined,\n                }\n            );\n        });\n    });\n\n    it('should call crudGetManyReference when its props changes', async () => {\n        const dataProvider = testDataProvider({\n            getManyReference: jest\n                .fn()\n                .mockResolvedValue({ data: [], total: 0 }),\n        });\n        const ControllerWrapper = props => (\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"id\"\n                    record={{ id: 123, name: 'James Joyce' }}\n                    sort={props.sort}\n                    reference=\"books\"\n                    target=\"author_id\"\n                >\n                    {() => 'null'}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n\n        const { rerender } = render(<ControllerWrapper />);\n        expect(dataProvider.getManyReference).toBeCalledTimes(1);\n        rerender(<ControllerWrapper sort={{ field: 'id', order: 'ASC' }} />);\n        await waitFor(() => {\n            expect(dataProvider.getManyReference).toBeCalledTimes(2);\n            expect(dataProvider.getManyReference).toHaveBeenCalledWith(\n                'books',\n                {\n                    id: 123,\n                    target: 'author_id',\n                    pagination: { page: 1, perPage: 25 },\n                    sort: { field: 'id', order: 'ASC' },\n                    filter: {},\n                    signal: undefined,\n                }\n            );\n        });\n    });\n\n    it('should take only last change in case of a burst of setFilters calls (case of inputs being currently edited)', async () => {\n        let childFunction = ({ setFilters, filterValues }) => (\n            <input\n                aria-label=\"search\"\n                type=\"text\"\n                value={filterValues.q || ''}\n                onChange={event => {\n                    setFilters({ q: event.target.value }, undefined, true);\n                }}\n            />\n        );\n        const dataProvider = testDataProvider({\n            getManyReference: jest\n                .fn()\n                .mockResolvedValue({ data: [], total: 0 }),\n        });\n        render(\n            <CoreAdminContext dataProvider={dataProvider}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"id\"\n                    record={{ id: 123, name: 'James Joyce' }}\n                    reference=\"books\"\n                    target=\"author_id\"\n                >\n                    {childFunction}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n        const searchInput = screen.getByLabelText('search');\n\n        fireEvent.change(searchInput, { target: { value: 'hel' } });\n        fireEvent.change(searchInput, { target: { value: 'hell' } });\n        fireEvent.change(searchInput, { target: { value: 'hello' } });\n\n        await waitFor(() => new Promise(resolve => setTimeout(resolve, 600)));\n\n        // Called twice: on load and on filter changes\n        expect(dataProvider.getManyReference).toHaveBeenCalledTimes(2);\n        expect(dataProvider.getManyReference).toHaveBeenCalledWith('books', {\n            target: 'author_id',\n            id: 123,\n            filter: { q: 'hello' },\n            pagination: { page: 1, perPage: 25 },\n            sort: { field: 'id', order: 'DESC' },\n            meta: undefined,\n            signal: undefined,\n        });\n    });\n\n    it('should support custom storeKey', async () => {\n        const store = memoryStore();\n        const setStore = jest.spyOn(store, 'setItem');\n\n        render(\n            <CoreAdminContext store={store}>\n                <ReferenceManyFieldController\n                    resource=\"authors\"\n                    source=\"uniqueName\"\n                    record={{\n                        id: 123,\n                        uniqueName: 'jamesjoyce256',\n                        name: 'James Joyce',\n                    }}\n                    reference=\"books\"\n                    target=\"author_id\"\n                    storeKey=\"customKey\"\n                >\n                    {({ onToggleItem }) => {\n                        return (\n                            <button onClick={() => onToggleItem(123)}>\n                                Toggle\n                            </button>\n                        );\n                    }}\n                </ReferenceManyFieldController>\n            </CoreAdminContext>\n        );\n\n        fireEvent.click(await screen.findByText('Toggle'));\n        await waitFor(() => {\n            expect(setStore).toHaveBeenCalledWith('customKey.selectedIds', [\n                123,\n            ]);\n        });\n    });\n\n    describe('response metadata', () => {\n        it('should return response metadata as meta', async () => {\n            const dataProvider = testDataProvider({\n                getManyReference: () =>\n                    Promise.resolve({\n                        data: [\n                            { id: 1, title: 'hello' },\n                            { id: 2, title: 'world' },\n                        ],\n                        total: 2,\n                        meta: {\n                            facets: [\n                                { foo: 'bar', count: 1 },\n                                { foo: 'baz', count: 2 },\n                            ],\n                        },\n                    }) as any,\n            });\n\n            const ListMetadataInspector = () => {\n                const listContext = useReferenceManyFieldController({\n                    resource: 'authors',\n                    source: 'id',\n                    record: { id: 123, name: 'James Joyce' },\n                    reference: 'books',\n                    target: 'author_id',\n                });\n\n                return (\n                    <>\n                        Response metadata:{' '}\n                        <pre>{JSON.stringify(listContext.meta, null)}</pre>\n                    </>\n                );\n            };\n\n            render(\n                <CoreAdminContext dataProvider={dataProvider}>\n                    <ListMetadataInspector />\n                </CoreAdminContext>\n            );\n\n            await screen.findByText(\n                '{\"facets\":[{\"foo\":\"bar\",\"count\":1},{\"foo\":\"baz\",\"count\":2}]}'\n            );\n        });\n    });\n});\n"],"version":3}
