m 'ra-core';\nimport polyglotI18nProvider from 'ra-i18n-polyglot';\nimport englishMessages from 'ra-language-english';\nimport { Box, Card, Stack } from '@mui/material';\n\nimport { TextInput } from '../input';\nimport { SimpleForm } from '../form/SimpleForm';\nimport { ListButton, SaveButton } from '../button';\nimport TopToolbar from '../layout/TopToolbar';\nimport { Create } from './Create';\n\nexport default { title: 'ra-ui-materialui/detail/Create' };\n\nconst dataProvider = testDataProvider();\n\nconst Content = () => <div>Create content</div>;\n\nexport const Basic = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create>\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const WithForm = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create>\n                        <Form>\n                            <Stack spacing={2} sx={{ padding: 2 }}>\n                                <TextInput source=\"title\" />\n                                <TextInput source=\"author\" />\n                                <TextInput source=\"summary\" />\n                                <TextInput source=\"year\" />\n                            </Stack>\n                            <SaveButton />\n                        </Form>\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const Actions = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create\n                        actions={\n                            <TopToolbar>\n                                <ListButton />\n                            </TopToolbar>\n                        }\n                    >\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const Title = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create title=\"Hello\">\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const TitleElement = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create title={<span>Hello</span>}>\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const TitleFalse = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create title={false}>\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nconst AsideComponent = () => <Card sx={{ padding: 2 }}>Aside</Card>;\n\nexport const Aside = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create aside={<AsideComponent />}>\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nconst CustomWrapper = ({ children }) => (\n    <Box\n        sx={{ padding: 2, width: 200, border: 'solid 1px black' }}\n        data-testid=\"custom-component\"\n    >\n        {children}\n    </Box>\n);\n\nexport const Component = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create component={CustomWrapper}>\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const SX = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create\n                        sx={{\n                            padding: 2,\n                            border: '1px solid red',\n                        }}\n                    >\n                        <Content />\n                    </Create>\n                )}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nconst CreateContent = () => {\n    const { save } = useCreateContext();\n    return <button onClick={save}>Save</button>;\n};\n\nconst dataProviderWithCreate = {\n    create: async () =>\n        ({\n            data: {\n                id: 1,\n                title: 'War and Peace',\n                author: 'Leo Tolstoy',\n                summary:\n                    \"War and Peace broadly focuses on Napoleon's invasion of Russia, and the impact it had on Tsarist society. The book explores themes such as revolution, revolution and empire, the growth and decline of various states and the impact it had on their economies, culture, and society.\",\n                year: 1869,\n            },\n        }) as any,\n} as any;\n\nexport const NotificationDefault = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProviderWithCreate}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create>\n                        <CreateContent />\n                    </Create>\n                )}\n                list={() => <span />}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const NotificationTranslated = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin\n            dataProvider={dataProviderWithCreate}\n            i18nProvider={polyglotI18nProvider(\n                () => ({\n                    ...englishMessages,\n                    resources: {\n                        books: { notifications: { created: 'Book created' } },\n                    },\n                }),\n                'en'\n            )}\n        >\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create>\n                        <CreateContent />\n                    </Create>\n                )}\n                list={() => <span />}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n\nexport const Default = () => (\n    <TestMemoryRouter initialEntries={['/books/create']}>\n        <Admin dataProvider={dataProvider}>\n            <Resource\n                name=\"books\"\n                create={() => (\n                    <Create>\n                        <SimpleForm>\n                            <TextInput source=\"title\" />\n                            <TextInput source=\"author\" />\n                            <TextInput source=\"summary\" />\n                            <TextInput source=\"year\" />\n                        </SimpleForm>\n                    </Create>\n                )}\n                show={() => <span />}\n            />\n        </Admin>\n    </TestMemoryRouter>\n);\n"],"version":3}
