,QAAE,YAAY,CAAC,MAAM,EAAE,WAAW,CAAC,CAAU,CACvD;YACA,SAAS,IAAI,CACV,oBAAC,uBAAY,QACR,SAAS,CAAC,MAAM,EAAE,MAAM,CAAC,EAAE,CAAC,CAClB,CAClB,CACqB,CAC7B,CACF,CACN,CAAC;AACN,CAAC,CAAC;AAEF,IAAM,MAAM,GAAG,cAAc,CAAC;AAEjB,QAAA,iBAAiB,GAAG;IAC7B,QAAQ,EAAE,UAAG,MAAM,cAAW;CACjC,CAAC;AAEF,IAAM,IAAI,GAAG,IAAA,eAAM,EAAC,eAAI,EAAE;IACtB,IAAI,EAAE,MAAM;IACZ,iBAAiB,EAAE,UAAC,KAAK,EAAE,MAAM,IAAK,OAAA,MAAM,CAAC,IAAI,EAAX,CAAW;CACpD,CAAC;IACE,GAAC,aAAM,yBAAiB,CAAC,QAAQ,CAAE,IAAG,EAAE,KAAK,EAAE,OAAO,EAAE,OAAO,EAAE,QAAQ,EAAE;QAC7E,CAAC;AAEH,IAAM,YAAY,GAAG,oBAAC,6BAAa,OAAG,CAAC","names":[],"sources":["/workspace/repo/packages/ra-ui-materialui/src/list/SimpleList/SimpleList.tsx"],"sourcesContent":["import {\n    Avatar,\n    List,\n    ListItemAvatar,\n    ListItemIcon,\n    ListItemSecondaryAction,\n    ListItemText,\n    ListProps,\n} from '@mui/material';\nimport { styled } from '@mui/material/styles';\nimport {\n    RaRecord,\n    RecordContextProvider,\n    sanitizeListRestProps,\n    useGetRecordRepresentation,\n    useListContextWithProps,\n    useRecordContext,\n    useResourceContext,\n    useTranslate,\n} from 'ra-core';\nimport * as React from 'react';\nimport { isValidElement, ReactElement } from 'react';\n\nimport { ListNoResults } from '../ListNoResults';\nimport { SimpleListLoading } from './SimpleListLoading';\nimport {\n    FunctionToElement,\n    SimpleListBaseProps,\n    SimpleListItem,\n    SimpleListItemProps,\n} from './SimpleListItem';\n\n/**\n * The <SimpleList> component renders a list of records as a Material UI <List>.\n * It is usually used as a child of react-admin's <List> and <ReferenceManyField> components.\n *\n * Also widely used on Mobile.\n *\n * Props:\n * - primaryText: function returning a React element (or some text) based on the record\n * - secondaryText: same\n * - tertiaryText: same\n * - leftAvatar: function returning a React element based on the record\n * - leftIcon: same\n * - rightAvatar: same\n * - rightIcon: same\n * - linkType: deprecated - 'edit' or 'show', or a function returning 'edit' or 'show' based on the record\n * - rowClick: The action to trigger when the user clicks on a row.\n * - rowStyle: function returning a style object based on (record, index)\n * - rowSx: function returning a sx object based on (record, index)\n *\n * @example // Display all posts as a List\n * const postRowSx = (record, index) => ({\n *     backgroundColor: record.views >= 500 ? '#efe' : 'white',\n * });\n * export const PostList = () => (\n *     <List>\n *         <SimpleList\n *             primaryText={record => record.title}\n *             secondaryText={record => `${record.views} views`}\n *             tertiaryText={record =>\n *                 new Date(record.published_at).toLocaleDateString()\n *             }\n *             rowSx={postRowSx}\n *          />\n *     </List>\n * );\n */\nexport const SimpleList = <RecordType extends RaRecord = any>(\n    props: SimpleListProps<RecordType>\n) => {\n    const {\n        className,\n        empty = DefaultEmpty,\n        hasBulkActions,\n        leftAvatar,\n        leftIcon,\n        linkType,\n        rowClick,\n        primaryText,\n        rightAvatar,\n        rightIcon,\n        secondaryText,\n        tertiaryText,\n        ref,\n        rowSx,\n        rowStyle,\n        ...rest\n    } = props;\n    const { data, isPending, total } =\n        useListContextWithProps<RecordType>(props);\n\n    if (isPending === true) {\n        return (\n            <SimpleListLoading\n                className={className}\n                hasLeftAvatarOrIcon={!!leftIcon || !!leftAvatar}\n                hasRightAvatarOrIcon={!!rightIcon || !!rightAvatar}\n                hasSecondaryText={!!secondaryText}\n                hasTertiaryText={!!tertiaryText}\n            />\n        );\n    }\n\n    if (data == null || data.length === 0 || total === 0) {\n        if (empty) {\n            return empty;\n        }\n\n        return null;\n    }\n\n    return (\n        <Root className={className} {...sanitizeListRestProps(rest)}>\n            {data.map((record, rowIndex) => (\n                <RecordContextProvider key={record.id} value={record}>\n                    <SimpleListItem\n                        key={record.id}\n                        rowIndex={rowIndex}\n                        linkType={linkType}\n                        rowClick={rowClick}\n                        rowSx={rowSx}\n                        rowStyle={rowStyle}\n                    >\n                        <SimpleListItemContent\n                            leftAvatar={leftAvatar}\n                            leftIcon={leftIcon}\n                            primaryText={primaryText}\n                            rightAvatar={rightAvatar}\n                            rightIcon={rightIcon}\n                            secondaryText={secondaryText}\n                            tertiaryText={tertiaryText}\n                            rowIndex={rowIndex}\n                        />\n                    </SimpleListItem>\n                </RecordContextProvider>\n            ))}\n        </Root>\n    );\n};\n\nexport interface SimpleListProps<RecordType extends RaRecord = any>\n    extends SimpleListBaseProps<RecordType>,\n        Omit<ListProps, 'classes'> {\n    className?: string;\n    empty?: ReactElement;\n    hasBulkActions?: boolean;\n    // can be injected when using the component without context\n    resource?: string;\n    data?: RecordType[];\n    isLoading?: boolean;\n    isPending?: boolean;\n    isLoaded?: boolean;\n    total?: number;\n}\n\nconst SimpleListItemContent = <RecordType extends RaRecord = any>(\n    props: SimpleListItemProps<RecordType>\n) => {\n    const {\n        leftAvatar,\n        leftIcon,\n        primaryText,\n        rightAvatar,\n        rightIcon,\n        secondaryText,\n        tertiaryText,\n    } = props;\n    const resource = useResourceContext(props);\n    const record = useRecordContext<RecordType>(props);\n    const getRecordRepresentation = useGetRecordRepresentation(resource);\n    const translate = useTranslate();\n\n    const renderAvatar = (\n        record: RecordType,\n        avatarCallback: FunctionToElement<RecordType>\n    ) => {\n        const avatarValue = avatarCallback(record, record.id);\n        if (\n            typeof avatarValue === 'string' &&\n            (avatarValue.startsWith('http') || avatarValue.startsWith('data:'))\n        ) {\n            return <Avatar src={avatarValue} />;\n        } else {\n            return <Avatar>{avatarValue}</Avatar>;\n        }\n    };\n\n    if (!record) return null;\n\n    return (\n        <>\n            {leftIcon && (\n                <ListItemIcon>{leftIcon(record, record.id)}</ListItemIcon>\n            )}\n            {leftAvatar && (\n                <ListItemAvatar>\n                    {renderAvatar(record, leftAvatar)}\n                </ListItemAvatar>\n            )}\n            <ListItemText\n                primary={\n                    <div>\n                        {primaryText\n                            ? typeof primaryText === 'string'\n                                ? translate(primaryText, {\n                                      ...record,\n                                      _: primaryText,\n                                  })\n                                : isValidElement(primaryText)\n                                  ? primaryText\n                                  : // @ts-ignore\n                                    primaryText(record, record.id)\n                            : getRecordRepresentation(record)}\n\n                        {!!tertiaryText &&\n                            (isValidElement(tertiaryText) ? (\n                                tertiaryText\n                            ) : (\n                                <span className={SimpleListClasses.tertiary}>\n                                    {typeof tertiaryText === 'string'\n                                        ? translate(tertiaryText, {\n                                              ...record,\n                                              _: tertiaryText,\n                                          })\n                                        : isValidElement(tertiaryText)\n                                          ? tertiaryText\n                                          : // @ts-ignore\n                                            tertiaryText(record, record.id)}\n                                </span>\n                            ))}\n                    </div>\n                }\n                secondary={\n                    !!secondaryText &&\n                    (typeof secondaryText === 'string'\n                        ? translate(secondaryText, {\n                              ...record,\n                              _: secondaryText,\n                          })\n                        : isValidElement(secondaryText)\n                          ? secondaryText\n                          : // @ts-ignore\n                            secondaryText(record, record.id))\n                }\n            />\n            {(rightAvatar || rightIcon) && (\n                <ListItemSecondaryAction>\n                    {rightAvatar && (\n                        <Avatar>{renderAvatar(record, rightAvatar)}</Avatar>\n                    )}\n                    {rightIcon && (\n                        <ListItemIcon>\n                            {rightIcon(record, record.id)}\n                        </ListItemIcon>\n                    )}\n                </ListItemSecondaryAction>\n            )}\n        </>\n    );\n};\n\nconst PREFIX = 'RaSimpleList';\n\nexport const SimpleListClasses = {\n    tertiary: `${PREFIX}-tertiary`,\n};\n\nconst Root = styled(List, {\n    name: PREFIX,\n    overridesResolver: (props, styles) => styles.root,\n})({\n    [`& .${SimpleListClasses.tertiary}`]: { float: 'right', opacity: 0.541176 },\n});\n\nconst DefaultEmpty = <ListNoResults />;\n"],"version":3}
