, 1902, and 1909.',\n    year: 1869,\n};\n\nconst Wrapper = ({\n    children,\n    record = data,\n}: {\n    children: React.ReactNode;\n    record?: RaRecord;\n}) => (\n    <TestMemoryRouter\n        initialEntries={[`/books/${encodeURIComponent(record.id)}`]}\n    >\n        <AdminContext\n            i18nProvider={{\n                translate: (x, options) => options?._ ?? x,\n                changeLocale: () => Promise.resolve(),\n                getLocale: () => 'en',\n            }}\n            dataProvider={testDataProvider({\n                // @ts-ignore\n                getOne: () => Promise.resolve({ data: record }),\n            })}\n            defaultTheme=\"light\"\n        >\n            <ResourceContextProvider value=\"books\">\n                <Routes>\n                    <Route\n                        path=\"/books/:id/*\"\n                        element={<Edit sx={{ width: 600 }}>{children}</Edit>}\n                    />\n                </Routes>\n            </ResourceContextProvider>\n        </AdminContext>\n    </TestMemoryRouter>\n);\n\nexport const Basic = () => (\n    <Wrapper>\n        <TabbedForm>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" />\n                <NumberInput source=\"year\" />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nexport const MultipleTabs = () => (\n    <Wrapper>\n        <TabbedForm>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" />\n                <NumberInput source=\"year\" />\n            </TabbedForm.Tab>\n            <TabbedForm.Tab label=\"details\">\n                <TextInput multiline source=\"bio\" />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nexport const CustomLayout = () => (\n    <Wrapper>\n        <TabbedForm>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <Stack direction=\"row\" gap={1} width=\"100%\">\n                    <TextInput source=\"author\" sx={{ width: '50%' }} />\n                    <NumberInput source=\"year\" sx={{ width: '50%' }} />\n                </Stack>\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nexport const NoToolbar = () => (\n    <Wrapper>\n        <TabbedForm toolbar={false}>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" sx={{ width: '50%' }} />\n                <NumberInput source=\"year\" sx={{ width: '50%' }} />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nexport const Count = () => (\n    <Wrapper>\n        <TabbedForm>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" />\n                <NumberInput source=\"year\" />\n            </TabbedForm.Tab>\n            <TabbedForm.Tab label=\"comments\" count={3}>\n                <TextInput multiline source=\"bio\" />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nexport const Validate = () => (\n    <Wrapper>\n        <TabbedForm validate={() => ({ bio: 'incorrect details' })}>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" />\n                <NumberInput source=\"year\" />\n            </TabbedForm.Tab>\n            <TabbedForm.Tab label=\"details\">\n                <TextInput multiline source=\"bio\" />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nconst zodSchema = z.object({\n    title: z.string().min(5),\n    author: z.string().min(5),\n    bio: z.string().min(5),\n});\n\nexport const Resolver = () => (\n    <Wrapper>\n        <TabbedForm resolver={zodResolver(zodSchema)}>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" />\n                <NumberInput source=\"year\" />\n            </TabbedForm.Tab>\n            <TabbedForm.Tab label=\"details\">\n                <TextInput multiline source=\"bio\" />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n\nconst dataWithEncodedId = {\n    id: '1:prod:resource1',\n    title: 'War and Peace',\n    author: 'Leo Tolstoy',\n    bio: 'Leo Tolstoy (1828-1910) was a Russian writer who is regarded as one of the greatest authors of all time. He received nominations for the Nobel Prize in Literature every year from 1902 to 1906 and for the Nobel Peace Prize in 1901, 1902, and 1909.',\n    year: 1869,\n};\nexport const EncodedPaths = () => (\n    <Wrapper record={dataWithEncodedId}>\n        <TabbedForm>\n            <TabbedForm.Tab label=\"main\">\n                <TextInput source=\"title\" />\n                <TextInput source=\"author\" />\n                <NumberInput source=\"year\" />\n            </TabbedForm.Tab>\n            <TabbedForm.Tab label=\"details\">\n                <TextInput multiline source=\"bio\" />\n            </TabbedForm.Tab>\n        </TabbedForm>\n    </Wrapper>\n);\n"],"version":3}
